    candleAnatomyTitle: 'Anatomía de una vela japonesa',
    candleAnatomyIntro: 'Cada vela representa 4 datos OHLC del periodo: apertura, máximo, mínimo y cierre. El cuerpo (sólido) muestra el movimiento entre apertura y cierre; las mechas marcan los extremos del rango.',
