    leverageRiskRule3: 'Ajusta el tamaño de posición para que el precio de liquidación esté DETRÁS de tu stop, nunca delante.',
    pillarsTitle: 'Los 3 pilares del trading: ¿de qué está realmente hecho?',
    pillarsIntro: 'No es una fórmula exacta, pero sí el modelo mental más usado en la formación seria. Si psicología y gestión fallan, el análisis ni siquiera importa.',
    pillarPsychologyName: 'Psicología / Mentalidad',
    pillarPsychologyShort: 'Casi la mitad de tu trabajo: control emocional, rutinas, foco en consistencia.',
    pillarPsychologyP1: 'Controlar miedo, ansiedad y la urgencia de "vencer al mercado".',
    pillarPsychologyP2: 'Fijar rutinas: no operar cansado, cabreado, ni "vengarte".',
    pillarPsychologyP3: 'Foco en consistencia de ejecución, no en cuánto ganas hoy.',
    pillarRiskName: 'Gestión del Riesgo',
    pillarRiskShort: 'Tamaño de posición, % por trade, R:R. Sin esto, hasta el mejor sistema quiebra.',
    pillarRiskP1: 'Arriesgar 0,5–1 % del capital por operación, máximo 2 %.',
    pillarRiskP2: 'Ajustar tamaño de posición según la distancia al stop.',
    pillarRiskP3: 'Buscar relación riesgo/beneficio mínimo 1:2 (idealmente 1:3).',
    pillarAnalysisName: 'Análisis Técnico',
    pillarAnalysisShort: 'Lo que más se enseña, pero el menor margen de mejora una vez tienes un sistema claro.',
    pillarAnalysisP1: 'Elegir 1–2 señales claras para tu temporalidad y stickerlas.',
    pillarAnalysisP2: 'Saber cuándo NO operar (rangos sin contexto, noticias, ruido).',
    pillarAnalysisP3: 'Un sistema simple bien ejecutado supera a 10 sistemas complejos.',
    pillarsTimeTitle: 'Reparto de tu tiempo de estudio',
    pillarsTimeIntro: 'Si dedicas {hours} horas a la semana al trading, esta es la distribución recomendada:',
    pillarsTimeWeekly: 'horas / semana',
    pillarsKeyQuote: 'Si tu psicología es floja, aunque el análisis sea "perfecto", romperás reglas, cerrarás antes y moverás tus stops.',
    expandingPatternsTitle: 'Patrones de Expansión Avanzados (Broadening)',
    expandingPatternsIntro: 'A diferencia de los triángulos clásicos que se contraen, estos patrones se EXPANDEN: las líneas de tendencia divergen formando máximos crecientes y mínimos decrecientes. Reflejan indecisión y volatilidad creciente. La estrategia usa 2 entradas (E1 = primera ruptura, E2 = retest confirmado) con doble take profit (T1 = altura del patrón, T2 = proyección extendida).',
    expandingPatternsTradePlan: 'Plan de Trading',
    expandingPatternsTarget: 'Objetivo (altura proyectada)',
    expandingPatternsAscWedgeName: 'Cuña de Expansión Ascendente',
    expandingPatternsAscWedgeDesc: 'Patrón de REVERSIÓN BAJISTA en tendencia alcista madura. Las dos líneas suben pero divergen creando volatilidad creciente. La ruptura de la línea inferior dispara una corrección fuerte. Stop Loss sobre el último máximo, objetivo = altura de la cuña proyectada hacia abajo.',
    expandingPatternsBullContName: 'Triángulo Expansivo Alcista (Continuación)',
    expandingPatternsBullContDesc: 'Patrón de CONTINUACIÓN ALCISTA. La cuña expansiva ascendente actúa como zona de acumulación dentro de una tendencia alcista. La ruptura al alza valida la continuación. T1 = altura mínima, T2 = altura completa proyectada.',
    expandingPatternsBearRevName: 'Triángulo Expansivo Bajista (Cambio Alcista)',
    expandingPatternsBearRevDesc: 'Patrón de REVERSIÓN ALCISTA al final de una tendencia bajista. La presión vendedora se debilita, los compradores empiezan a aparecer en mínimos crecientes. Ruptura al alza = nuevo ciclo alcista. Doble entrada con stops debajo del último mínimo.',
    expandingPatternsBearContName: 'Triángulo Expansivo Bajista (Continuación)',
    expandingPatternsBearContDesc: 'Patrón de CONTINUACIÓN BAJISTA. Pausa volátil en una tendencia bajista clara antes de retomar la caída. La ruptura a la baja confirma la continuación con objetivo igual a la altura de la formación.',
    expandingPatternsBearRevDownName: 'Triángulo Expansivo Bajista (Cambio Bajista)',
    expandingPatternsBearRevDownDesc: 'Patrón de REVERSIÓN BAJISTA tras una tendencia alcista. Los máximos crecientes son cada vez más débiles y los compradores pierden control. La ruptura del soporte inferior confirma el cambio de tendencia.',
    vBottomReversalName: 'Suelo en V (Cambio Alcista)',
    vBottomReversalDesc: 'Patrón de reversión brusca: tras una caída sostenida el precio forma un mínimo agudo en V y rebota con fuerza. Confirma cambio de tendencia bajista a alcista.',
    vBottomReversalHTT_1: 'Entry 1: comprar al romper al alza la línea de resistencia previa al V',
    vBottomReversalHTT_2: 'Entry 2: comprar en el retest del soporte recién creado',
    vBottomReversalHTT_3: 'Stop Loss: por debajo del mínimo del V',
    vBottomReversalHTT_4: 'Take Profit 1 y 2: distancia equivalente a la profundidad del V proyectada al alza',
    vBottomReversalHTT_5: 'Confirmación: vela alcista con volumen creciente al romper resistencia',
    vBottomContinuationName: 'Suelo en V (Continuación Alcista)',
    vBottomContinuationDesc: 'Patrón de continuación dentro de tendencia alcista: el precio realiza una pequeña corrección en forma de V y reanuda el movimiento alcista al superar el último máximo. Útil para añadir posiciones en tendencia.',
    vBottomContinuationHTT_1: 'Entry 1: comprar al romper al alza el último máximo previo al V',
    vBottomContinuationHTT_2: 'Entry 2: comprar en el retest de ese máximo (ahora soporte)',
    vBottomContinuationHTT_3: 'Stop Loss: por debajo del mínimo del V',
    vBottomContinuationHTT_4: 'Take Profit 1 y 2: proyectar la distancia del swing previo al V',
    vBottomContinuationHTT_5: 'Confirmación: alineación con la tendencia alcista mayor (EMA50 al alza)',
    risingWedgeName: 'Cuña Ascendente',
    risingWedgeDesc: 'Patrón de REVERSIÓN BAJISTA. Las dos líneas suben pero convergen hacia un punto. Aunque el precio sube, lo hace con menos fuerza cada vez. La ruptura por debajo de la línea inferior dispara una caída fuerte.',
    risingWedgeHTT_1: 'Esperar al menos 2 toques de cada línea (4 puntos mínimo)',
    risingWedgeHTT_2: 'Entry: vender en ruptura confirmada de la línea inferior con volumen',
