    probabilityStatsIntro: 'La probabilidad y estadística son la base matemática del trading exitoso. Entender estos conceptos te permite tomar decisiones racionales basadas en datos, no en emociones.',
    
    mathematicalExpectationTitle: 'Expectativa Matemática',
    expectationFormulaTitle: 'Fórmula de Expectativa',
    expectationFormulaDesc: 'E = (Win% × Avg Win) - (Loss% × Avg Loss). Esta es LA métrica más importante. Si E > 0, tu estrategia es rentable a largo plazo. Ejemplo: 50% win rate, avg win $200, avg loss $100 → E = (0.5 × 200) - (0.5 × 100) = $50 por trade.',
    
    whyExpectationMattersTitle: 'Por Qué Es La Métrica Clave',
    whyExpectationMattersDesc: 'Puedes tener 30% de acierto y ser rentable si tus ganancias son 3x tus pérdidas. O tener 70% de acierto y perder dinero si tus pérdidas son mayores que tus ganancias. La expectativa lo resume todo.',
    
    lawOfLargeNumbersTitle: 'Ley de los Grandes Números',
    largeNumbersConceptTitle: 'Concepto',
    largeNumbersConceptDesc: 'Tu edge (ventaja) solo se manifiesta con suficientes trades. 10 trades no son suficientes. 100 trades empiezan a ser representativos. 300+ trades dan confianza estadística. A corto plazo, la suerte domina. A largo plazo, la probabilidad converge.',
    
    varianceShortTermTitle: 'Varianza a Corto Plazo',
    varianceShortTermDesc: 'Incluso con 60% win rate, puedes tener 5-7 pérdidas consecutivas. Esto NO significa que tu estrategia no funciona. Es varianza normal. Por eso necesitas gestión de capital: para sobrevivir las rachas malas.',
    
    resultsDistributionTitle: 'Distribución de Resultados',
    normalDistributionTitle: 'Realidad vs Teoría',
    normalDistributionDesc: 'Los libros asumen distribución normal (curva de campana). La realidad del trading tiene "colas gordas" (fat tails): eventos extremos ocurren más seguido de lo esperado. Prepárate para cisnes negros (crashes inesperados).',
    
    outliersImpactTitle: 'Impacto de Outliers',
    outliersImpactDesc: 'A veces, el 80% de tus ganancias anuales vienen del 20% de tus trades (Principio de Pareto). No puedes predecir cuáles serán. Por eso NUNCA saltarse un trade de tu estrategia: podrías perderte el outlier ganador.',
    
    streaksManagementTitle: 'Gestión de Rachas',
    losingStreakProbTitle: 'Probabilidad de Rachas Perdedoras',
    losingStreakProbDesc: 'Fórmula: P(N pérdidas) = (Loss Rate)^N. Ejemplo con 40% loss rate: 1 pérdida = 40%, 2 seguidas = 16%, 3 seguidas = 6.4%, 5 seguidas = 1%. Con 100 trades, estadísticamente tendrás al menos una racha de 5 pérdidas.',
    
    psychologicalImpactTitle: 'Impacto Psicológico',
    psychologicalImpactDesc: 'Saber que rachas de 5-7 pérdidas son estadísticamente normales te ayuda a NO abandonar tu estrategia prematuramente. El trader promedio abandona su sistema justo antes de que la racha ganadora llegue.',
    
    varianceStdDevTitle: 'Varianza y Desviación Estándar',
    volatilityOfResultsTitle: 'Volatilidad de tus Resultados',
    volatilityOfResultsDesc: 'Desviación estándar mide cuánto varían tus resultados. Baja desviación = resultados consistentes. Alta desviación = resultados erráticos. Dos traders con misma expectativa pueden tener experiencias MUY diferentes según su desviación estándar.',
    
    sharpeRatioTitle: 'Sharpe Ratio',
    sharpeRatioDesc: 'Fórmula: (Retorno - Tasa libre riesgo) / Desviación Estándar. Mide retorno ajustado por riesgo. Sharpe > 1 = bueno. Sharpe > 2 = excelente. Sharpe > 3 = excepcional. Prefiere estrategias con Sharpe alto: menos estrés, más consistencia.',
    
    correlationTitle: 'Correlación entre Activos',
    correlationConceptTitle: 'Coeficiente de Correlación',
    correlationConceptDesc: 'Mide relación entre dos activos. +1 = se mueven igual. 0 = independientes. -1 = se mueven opuesto. BTC y ETH tienen correlación ~0.8-0.9 (alta). BTC y USD tienen correlación negativa (~-0.3).',
    
    diversificationCorrelationTitle: 'Diversificación Inteligente',
    diversificationCorrelationDesc: 'No basta con operar 5 activos. Si todos tienen correlación +0.9, es como operar 1 solo activo. Busca activos con correlación <0.3 para verdadera diversificación. Ejemplo: Crypto + Bonos + Oro tienen baja correlación.',
    
    keyMetricsTitle: 'Métricas Estadísticas Clave',
    winRateMetricTitle: 'Win Rate (Tasa de Acierto)',
    winRateMetricDesc: 'Trades ganadores / Total trades. 60% win rate es excelente. 50% es bueno. <40% requiere R:R muy alto. CUIDADO: Win rate solo NO dice nada. Un sistema con 90% win rate puede quebrar si la pérdida del 10% es enorme.',
    
    profitFactorMetricTitle: 'Profit Factor',
    profitFactorMetricDesc: 'Ganancias brutas / Pérdidas brutas. PF > 1.5 = bueno. PF > 2 = excelente. PF > 3 = excepcional. Ejemplo: $10,000 ganados, $5,000 perdidos → PF = 2. Significa que ganas $2 por cada $1 que pierdes.',
    
    rMultipleMetricTitle: 'R-Múltiplo Promedio',
    rMultipleMetricDesc: '1R = tu riesgo inicial (distancia a stop loss). Si arriesgas $100 y ganas $300, es 3R. Si pierdes, es -1R. R-múltiplo promedio > 0.5 es bueno. > 1 es excelente. Permite comparar estrategias de diferentes mercados.',
    
    maxDrawdownMetricTitle: 'Maximum Drawdown',
    maxDrawdownMetricDesc: 'Caída máxima desde pico hasta valle. Si tu cuenta pasó de $10,000 a $7,000, MDD = 30%. Drawdowns de 20-30% son normales incluso para buenos traders. >50% es peligroso. Planifica para el peor escenario.',
    
    backtestingStatsTitle: 'Backtesting Estadístico',
    sampleSizeTitle: 'Tamaño de Muestra Necesario',
    sampleSizeDesc: 'Mínimo 100 trades para empezar a tener confianza. 300+ trades para confianza estadística. <30 trades es anecdótico, no estadístico. No lances una estrategia live con solo 20 backtests: la varianza te puede engañar.',
    
    overfittingDangerTitle: 'Peligro del Overfitting',
    overfittingDangerDesc: 'Optimizar tu estrategia hasta que funcione perfectamente en datos históricos es una trampa. Estás ajustando al ruido, no a la señal. Resultado: 95% win rate en backtest, 35% en real. Solución: Out-of-sample testing (datos que NO usaste para optimizar).',
    
    statisticalSignificanceTitle: 'Significancia Estadística',
    statisticalSignificanceDesc: 'Un backtest con 60% win rate puede ser suerte. Usa intervalos de confianza. Pregunta: "¿Qué probabilidad hay de que este resultado sea azar?" Si p-value < 0.05 (5%), tienes confianza estadística. De lo contrario, necesitas más datos.',
    
