    edu_fundamentosComprarVsVende_6227e3cc: 'Fundamentos: Comprar vs Vender Opciones',
    edu_todaOperacionConOpciones_4b806806: 'Toda operación con opciones tiene DOS PARTES. El que COMPRA (Long) paga la prima y obtiene un derecho. El que VENDE (Short) cobra la prima y acepta la obligación si se ejerce.',
    edu_lasGriegas_0ebfaf86: 'Las Griegas',
    edu_lasGriegasCuantificanLa_560a7bae: 'Las griegas cuantifican la sensibilidad de la prima ante distintos factores. Dominarlas es lo que separa al trader profesional del amateur.',
    edu_moneynessItmAtmOtm_a4a14296: 'Moneyness: ITM / ATM / OTM (explicado)',
    edu_laMoneynessIndicaLa_d33c00c2: 'La MONEYNESS indica la relación entre el precio actual del subyacente (Spot S) y el Strike K. Define el valor intrínseco de la opción y su comportamiento.',
    edu_volatilidadImplicitaIv_9566fdd4: 'Volatilidad Implícita (IV)',
    edu_laIvEsEl_8e2ceb1e: 'La IV es el precio del mercado para la incertidumbre futura. Una IV alta encarece las primas; una IV baja las abarata. Es el factor MÁS importante tras Delta.',
    edu_comoLeerElDiagrama_0e91a1f2: 'Cómo leer el diagrama de Payoff',
    edu_elGraficoDePayoff_4228af6d: 'El gráfico de payoff muestra el PnL (eje Y) en función del precio del subyacente al vencimiento (eje X). Las dos líneas clave son T+0 (hoy) y At Expiry (vencimiento).',
    edu_longCallBuyCall_b69bddbc: 'LONG CALL (BUY CALL) → Pagas prima. Ganas si sube > Strike+Prima. Pérdida máxima = prima pagada.',
