    edu_vegaSensibilidadAlCambio_49f4d565: 'Vega ν → Sensibilidad al cambio en la volatilidad implícita (IV). Positiva para Long, negativa para Short.',
    edu_gammaVelocidadDeCambio_2647e1e9: 'Gamma Γ → Velocidad de cambio del Delta; máximo cerca ATM. Largos: Gamma positivo. Cortos: Gamma negativo.',
    edu_rhoSensibilidadACambios_6dd807ab: 'Rho ρ → Sensibilidad a cambios en tipos de interés. Significativa solo para opciones a largo plazo (LEAPS).',
    edu_call_094692fa: '── CALL ──',
    edu_itmInTheMoney_d20317a8: 'ITM (In-The-Money) → S > K. Tiene valor intrínseco = S−K. Delta > 0.5. Comportamiento "como stock".',
