    expandingPatternsTitle: 'Advanced Broadening Patterns',
    expandingPatternsIntro: 'Unlike classic triangles that converge, these patterns EXPAND: the trendlines diverge forming higher highs and lower lows. They reflect indecision and rising volatility. The strategy uses 2 entries (E1 = first breakout, E2 = confirmed retest) with double take profit (T1 = pattern height, T2 = extended projection).',
