    expandingPatternsTarget: 'Target (projected height)',
    expandingPatternsAscWedgeName: 'Ascending Broadening Wedge',
    expandingPatternsAscWedgeDesc: 'BEARISH REVERSAL pattern in mature uptrend. Both lines rise but diverge creating growing volatility. The break below the lower line triggers a strong correction. Stop Loss above the last high, target = wedge height projected downward.',
    expandingPatternsBullContName: 'Bullish Broadening Triangle (Continuation)',
    expandingPatternsBullContDesc: 'BULLISH CONTINUATION pattern. The ascending broadening wedge acts as an accumulation zone inside an uptrend. Break above validates continuation. T1 = minimum height, T2 = full projected height.',
    expandingPatternsBearRevName: 'Bearish Broadening Triangle (Bullish Reversal)',
    expandingPatternsBearRevDesc: 'BULLISH REVERSAL pattern at the end of a downtrend. Selling pressure weakens, buyers start appearing on rising lows. Break above = new bullish cycle. Double entry with stops below the last low.',
