    perfCTAEducation: 'Explore Learning Center',
    perfCTAFooter: 'No credit card. No spam. Only a notification when modules are available.',
    outliersImpactTitle: 'Outliers Impact',
    outliersImpactDesc: 'Sometimes 80% of your annual profits come from 20% of your trades (Pareto Principle). You can\'t predict which ones. That\'s why NEVER skip a trade from your strategy: you might miss the winning outlier.',
    streaksManagementTitle: 'Streaks Management',
    losingStreakProbTitle: 'Losing Streak Probability',
    losingStreakProbDesc: 'Formula: P(N losses) = (Loss Rate)^N. Example with 40% loss rate: 1 loss = 40%, 2 consecutive = 16%, 3 consecutive = 6.4%, 5 consecutive = 1%. With 100 trades, you\'ll statistically have at least one 5-loss streak.',
    psychologicalImpactTitle: 'Psychological Impact',
    psychologicalImpactDesc: 'Knowing that 5-7 loss streaks are statistically normal helps you NOT abandon your strategy prematurely. Average trader quits their system right before the winning streak arrives.',
    varianceStdDevTitle: 'Variance & Standard Deviation',
    volatilityOfResultsTitle: 'Volatility of Your Results',
    volatilityOfResultsDesc: 'Standard deviation measures how much your results vary. Low deviation = consistent results. High deviation = erratic results. Two traders with same expectation can have VERY different experiences based on their standard deviation.',
    sharpeRatioTitle: 'Sharpe Ratio',
    sharpeRatioDesc: 'Formula: (Return - Risk-free rate) / Standard Deviation. Measures risk-adjusted return. Sharpe > 1 = good. Sharpe > 2 = excellent. Sharpe > 3 = exceptional. Prefer high Sharpe strategies: less stress, more consistency.',
    correlationTitle: 'Asset Correlation',
    correlationConceptTitle: 'Correlation Coefficient',
    correlationConceptDesc: 'Measures relationship between two assets. +1 = move together. 0 = independent. -1 = move opposite. BTC and ETH have ~0.8-0.9 correlation (high). BTC and USD have negative correlation (~-0.3).',
    diversificationCorrelationTitle: 'Smart Diversification',
    diversificationCorrelationDesc: 'Trading 5 assets isn\'t enough. If all have +0.9 correlation, it\'s like trading 1 asset. Seek assets with <0.3 correlation for true diversification. Example: Crypto + Bonds + Gold have low correlation.',
    keyMetricsTitle: 'Key Statistical Metrics',
    winRateMetricTitle: 'Win Rate',
    winRateMetricDesc: 'Winning trades / Total trades. 60% win rate is excellent. 50% is good. <40% requires very high R:R. CAUTION: Win rate alone means nothing. A 90% win rate system can go bankrupt if the 10% loss is huge.',
    profitFactorMetricTitle: 'Profit Factor',
    profitFactorMetricDesc: 'Gross profits / Gross losses. PF > 1.5 = good. PF > 2 = excellent. PF > 3 = exceptional. Example: $10,000 won, $5,000 lost → PF = 2. Means you win $2 for every $1 you lose.',
    rMultipleMetricTitle: 'Average R-Multiple',
    rMultipleMetricDesc: '1R = your initial risk (distance to stop loss). If you risk $100 and win $300, it\'s 3R. If you lose, it\'s -1R. Average R-multiple > 0.5 is good. > 1 is excellent. Allows comparing strategies across markets.',
    maxDrawdownMetricTitle: 'Maximum Drawdown',
    maxDrawdownMetricDesc: 'Maximum drop from peak to valley. If your account went from $10,000 to $7,000, MDD = 30%. Drawdowns of 20-30% are normal even for good traders. >50% is dangerous. Plan for worst-case scenario.',
    backtestingStatsTitle: 'Statistical Backtesting',
    sampleSizeTitle: 'Required Sample Size',
    sampleSizeDesc: 'Minimum 100 trades to start having confidence. 300+ trades for statistical confidence. <30 trades is anecdotal, not statistical. Don\'t launch a strategy live with only 20 backtests: variance can fool you.',
    overfittingDangerTitle: 'Overfitting Danger',
    overfittingDangerDesc: 'Optimizing your strategy until it works perfectly on historical data is a trap. You\'re fitting to noise, not signal. Result: 95% win rate in backtest, 35% in real trading. Solution: Out-of-sample testing (data you didn\'t use for optimization).',
    statisticalSignificanceTitle: 'Statistical Significance',
    statisticalSignificanceDesc: 'A backtest with 60% win rate might be luck. Use confidence intervals. Ask: "What\'s the probability this result is chance?" If p-value < 0.05 (5%), you have statistical confidence. Otherwise, you need more data.',
    
