      testimonialsTitle_l001: 'What traders are saying',
    testimonialsSubtitle_l002: 'Hundreds of professional and retail traders are already optimizing their strategies with Trading Calculator PRO.',
    faqTitle_l003: 'Frequently Asked Questions',
    faqSubtitle_l004: 'The most common questions before getting started.',
    testimonial1Quote_l010: 'I went from trading blind to having clear R/R metrics, position size, and win rate. My account no longer suffers brutal drawdowns.',
    testimonial1Author_l011: 'Carlos M.',
    testimonial1Role_l012: 'Crypto Day Trader · 4 years',
    testimonial2Quote_l020: 'The Strategy Optimizer and AI Coach save me hours of analysis. I justify the cost each month with a single well-planned trade.',
    testimonial2Author_l021: 'Ana R.',
    testimonial2Role_l022: 'Options Swing Trader',
    testimonial3Quote_l030: 'I\'ve been using it daily for 8 months. The Monte Carlo and journal changed the way I view risk. 5 stars.',
    testimonial3Author_l031: 'David L.',
    testimonial3Role_l032: 'Independent Trader · Forex',
    faqQ1_l040: 'Do I need to be an expert to use it?',
    faqA1_l041: 'No. The app guides you step-by-step through each calculator, and the Education Center covers everything from basics (what is a Stop Loss) to advanced options strategies. There\'s a free Demo Trader to try everything risk-free.',
    faqQ2_l050: 'Can I cancel my subscription anytime?',
    faqA2_l051: 'Yes. Cancel with 1 click from your profile. No commitment. If you purchase Lifetime, access is permanent—no recurring payments.',
    faqQ3_l060: 'What assets are supported?',
    faqA3_l061: 'Crypto, Forex (28 pairs), US Stocks (NYSE/NASDAQ), Indices (SPX, NDX, DAX, etc.), Commodities, and Futures. Real-time data via Yahoo Finance.',
    faqQ4_l070: 'Is the Trade Coach AI a separate charge?',
    faqA4_l071: 'No. The AI Trade Coach (Claude Sonnet 4.5) is included in all Premium plans. It analyzes your strategy, identifies risks, and suggests improvements like a senior mentor.',
    faqQ5_l080: 'Does it work on mobile?',
    faqA5_l081: 'Yes. Fully responsive design. Calculators and dashboard work perfectly on iOS/Android. Native app on Q2 roadmap.',
