    // Trading Rules Content (15 rules)
    rule1Title: 'Einen vollständigen Trading-Plan haben, bevor Sie handeln',
    rule1Explanation: 'Ein Trading-Plan sollte umfassen: Marktanalyse, Ein- und Ausstiegspunkte, Risikomanagement und Kriterien zur Leistungsbewertung. Ohne Plan spielen Sie, anstatt zu handeln.',
    rule2Title: 'Niemals mehr als 1-2% des Kapitals in einem Trade riskieren',
    rule2Explanation: 'Diese Regel schützt Sie vor katastrophalen Verlusten. Bei $10.000 sollte Ihr maximaler Verlust pro Trade $100-200 betragen. Dies ermöglicht es Ihnen, eine Verlustserie zu überstehen.',
    rule3Title: 'Dem Trading-Plan ohne Ausnahmen folgen',
    rule3Explanation: 'Emotionen sind der schlimmste Feind des Traders. Angst und Gier führen zu irrationalen Entscheidungen. Ein gut gestalteter Plan eliminiert Emotionen aus der Gleichung.',
    rule4Title: 'Auf Bestätigung warten, bevor Sie einsteigen',
    rule4Explanation: 'Antizipieren Sie die Bewegung nicht. Warten Sie, bis der Preis Ihre Analyse bestätigt. Ein vorzeitiger Einstieg kann zu einem unnötigen Stop Loss führen.',
    rule5Title: 'Stop Loss und Take Profit VOR dem Einstieg definieren',
    rule5Explanation: 'Zu wissen, wo genau Sie aussteigen, bevor Sie einsteigen, ermöglicht es Ihnen, das Risiko/Gewinn-Verhältnis zu berechnen und objektive Entscheidungen zu treffen. Verschieben Sie Ihren Stop Loss niemals nach unten.',
    rule6Title: 'Nicht handeln, wenn Sie emotional sind',
    rule6Explanation: 'Wenn Sie frustriert über einen Verlust, ängstlich oder euphorisch über einen Gewinn sind, ist Ihr Urteilsvermögen beeinträchtigt. Machen Sie eine Pause und kehren Sie zurück, wenn Sie ruhig sind.',
    rule7Title: 'Immer Stop Loss verwenden',
    rule7Explanation: 'Der Markt kann sich stärker gegen Sie bewegen als Sie denken. Ein Stop Loss ist Ihre Versicherung gegen Katastrophen. Ohne ihn kann ein Trade Ihr Konto zerstören.',
    rule8Title: 'Multiple Zeitrahmen analysieren',
    rule8Explanation: 'Bevor Sie einsteigen, überprüfen Sie den Trend in höheren Zeitrahmen. Ein Einstieg im 15-Minuten-Chart sollte mit dem 4-Stunden- und Tages-Trend übereinstimmen.',
    rule9Title: 'Nur mit Geld handeln, das Sie sich leisten können zu verlieren',
    rule9Explanation: 'Mit Mietgeld oder Notfallfonds zu handeln setzt Sie unter extremen emotionalen Druck. Trading erfordert Risikokapital, keine lebensnotwendigen Mittel.',
    rule10Title: 'Ein Trading-Tagebuch führen',
    rule10Explanation: 'Zeichnen Sie jeden Trade auf: Einstieg, Ausstieg, Grund, Emotion, Ergebnis. Analysieren Sie Muster in Ihren Fehlern und Erfolgen. Verbesserung kommt von Analyse, nicht von mehr Trades.',
    rule11Title: 'Der Markt hat immer Recht',
    rule11Explanation: 'Diskutieren Sie nicht mit dem Markt. Wenn Ihre Analyse fehlschlägt, akzeptieren Sie den Verlust und lernen Sie. Ego ist teuer im Trading.',
    rule12Title: 'Hebelwirkung mit äußerster Vorsicht verwenden',
    rule12Explanation: 'Hebelwirkung verstärkt sowohl Gewinne als auch Verluste. Anfänger sollten nicht mehr als 2-3x verwenden. Profis verwenden selten mehr als 10x.',
    rule13Title: 'Der Trend ist dein Freund',
    rule13Explanation: 'Handeln Sie in Richtung des Haupttrends. Gegen-Trend-Trading nur für sehr erfahrene Trader. Es ist einfacher, mit dem Momentum Geld zu verdienen.',
    rule14Title: 'Niemals Verlustpositionen aufstocken',
    rule14Explanation: 'Zu einer Verlustposition hinzuzufügen ist einer der häufigsten und teuersten Fehler. Wenn der Trade gegen Sie läuft, akzeptieren Sie den Verlust gemäß Ihrem Plan.',
    rule15Title: 'Gewinne laufen lassen',
    rule15Explanation: 'Viele Trader schneiden Gewinne vorzeitig ab und lassen Verluste laufen. Verwenden Sie Trailing Stops, um Gewinne zu schützen, während der Preis sich zu Ihren Gunsten bewegt.',
    
