    // Dow Theory - GERMAN
    dowTheoryTitle: 'Dow-Theorie',
    dowTheoryIntro: 'Die Dow-Theorie ist die Grundlage der modernen technischen Analyse, entwickelt von Charles Dow Ende des 19. Jahrhunderts. Sie legt fundamentale Prinzipien zum Verständnis von Marktbewegungen fest.',
    
    dowPrinciple1Title: '1. Der Markt diskontiert alles',
    dowPrinciple1Desc: 'Marktpreise spiegeln alle verfügbaren Informationen wider: fundamental, politisch, psychologisch und Erwartungen. Jeder Faktor, der Angebot und Nachfrage beeinflussen kann, ist bereits im Preis enthalten.',
    
    dowPrinciple2Title: '2. Der Markt hat drei Trends',
    dowPrinciple2Desc: 'Primärtrend: Hauptmarktbewegung von 1 bis mehreren Jahren. Sekundärtrend: Korrekturen gegen den Primärtrend, dauern Wochen oder Monate. Kleiner Trend: Kurzfristige Schwankungen von Tagen oder Wochen.',
    
    dowPrinciple3Title: '3. Haupttrends haben drei Phasen',
    dowPrinciple3Desc: 'Akkumulationsphase: Informierte Investoren kaufen, wenn die Stimmung negativ ist. Phase der öffentlichen Beteiligung: Die breite Öffentlichkeit erkennt den Trend und beteiligt sich. Distributionsphase: Informierte Investoren verkaufen, wenn der Optimismus auf dem Höhepunkt ist.',
    
    dowPrinciple4Title: '4. Indizes müssen sich gegenseitig bestätigen',
    dowPrinciple4Desc: 'Damit ein Trendsignal gültig ist, müssen verschiedene Marktindizes sich in die gleiche Richtung bewegen. Eine Divergenz zwischen Indizes deutet darauf hin, dass der Trend schwach oder falsch sein könnte.',
    
    dowPrinciple5Title: '5. Volumen muss den Trend bestätigen',
    dowPrinciple5Desc: 'Das Volumen sollte in Richtung des Haupttrends zunehmen. In einem Aufwärtstrend steigt das Volumen bei Rallyes und sinkt bei Korrekturen. Das Gegenteil tritt bei Abwärtstrends auf.',
    
    dowPrinciple6Title: '6. Ein Trend besteht fort, bis klare Signale seine Umkehr anzeigen',
    dowPrinciple6Desc: 'Ein Trend bleibt in Kraft, bis es definitive Beweise gibt, dass er sich geändert hat. Kleine Schwankungen reichen nicht aus, um eine Trendänderung anzuzeigen. Klare Umkehrmuster sind erforderlich.',
    
    dowApplicationTitle: 'Praktische Anwendung',
    dowApplicationDesc: 'Um die Dow-Theorie anzuwenden: 1) Identifizieren Sie den Primärtrend durch Beobachtung von Hochs und Tiefs. 2) Warten Sie auf Volumenbestätigung. 3) Suchen Sie nach Umkehrsignalen nur bei klaren Mustern. 4) Handeln Sie in Richtung des Haupttrends. 5) Nutzen Sie sekundäre Korrekturen als Einstiegspunkte.',
    
    dowLimitationsTitle: 'Einschränkungen',
    dowLimitationsDesc: 'Die Dow-Theorie sagt nicht die Dauer oder das Ausmaß von Trends voraus. Signale können spät eintreffen, nachdem die Bewegung bereits begonnen hat. Nicht geeignet für sehr kurzfristiges Trading. Funktioniert am besten in liquiden Märkten mit großen Kapitalisierungen.',
    
