    // Trading Rules Content (15 rules)
    rule1Title: 'Avoir un plan de trading complet avant de trader',
    rule1Explanation: 'Un plan de trading doit inclure: analyse de marché, points d\'entrée et sortie, gestion du risque, et critères d\'évaluation de la performance. Sans plan, vous pariez au lieu de trader.',
    rule2Title: 'Ne jamais risquer plus de 1-2% du capital sur une seule opération',
    rule2Explanation: 'Cette règle vous protège des pertes catastrophiques. Si vous avez $10,000, votre perte maximale par trade devrait être $100-200. Cela vous permet de survivre à une série de pertes.',
    rule3Title: 'Suivre le plan de trading sans exceptions',
    rule3Explanation: 'Les émotions sont le pire ennemi du trader. La peur et la cupidité vous feront prendre des décisions irrationnelles. Un plan bien conçu élimine l\'émotion de l\'équation.',
    rule4Title: 'Attendre la confirmation avant d\'entrer',
    rule4Explanation: 'N\'anticipez pas le mouvement. Attendez que le prix confirme votre analyse. Une entrée prématurée peut résulter en un stop loss inutile.',
    rule5Title: 'Définir stop loss et take profit AVANT d\'entrer',
    rule5Explanation: 'Savoir exactement où sortir avant d\'entrer vous permet de calculer le risque/bénéfice et de prendre des décisions objectives. Ne déplacez jamais votre stop loss vers le bas.',
    rule6Title: 'Ne pas trader quand vous êtes émotionnel',
    rule6Explanation: 'Si vous êtes frustré par une perte, anxieux, ou euphorique après un gain, votre jugement est compromis. Faites une pause et revenez quand vous êtes calme.',
    rule7Title: 'Toujours utiliser un stop loss',
    rule7Explanation: 'Le marché peut bouger contre vous plus que vous ne l\'imaginez. Un stop loss est votre assurance contre le désastre. Sans lui, une opération peut détruire votre compte.',
    rule8Title: 'Analyser plusieurs temporalités',
    rule8Explanation: 'Avant d\'entrer, vérifiez la tendance sur des temporalités supérieures. Une entrée en 15 minutes doit être alignée avec la tendance 4 heures et journalière.',
    rule9Title: 'Trader uniquement avec de l\'argent que vous pouvez vous permettre de perdre',
    rule9Explanation: 'Trader avec l\'argent du loyer ou des fonds d\'urgence vous mettra sous une pression émotionnelle extrême. Le trading nécessite du capital à risque, pas des fonds essentiels.',
    rule10Title: 'Tenir un journal de trading',
    rule10Explanation: 'Enregistrez chaque trade: entrée, sortie, raison, émotion, résultat. Analysez les patterns dans vos erreurs et succès. L\'amélioration vient de l\'analyse, pas de plus de trades.',
    rule11Title: 'Le marché a toujours raison',
    rule11Explanation: 'Ne discutez pas avec le marché. Si votre analyse échoue, acceptez la perte et apprenez. L\'ego coûte cher en trading.',
    rule12Title: 'Utiliser l\'effet de levier avec une extrême prudence',
    rule12Explanation: 'L\'effet de levier amplifie les gains et les pertes. Les débutants ne devraient pas utiliser plus de 2-3x. Les professionnels utilisent rarement plus de 10x.',
    rule13Title: 'La tendance est votre amie',
    rule13Explanation: 'Tradez dans le sens de la tendance principale. Le contre-tendance est réservé aux traders très expérimentés. Il est plus facile de gagner de l\'argent en suivant le momentum.',
    rule14Title: 'Ne jamais moyenner à la baisse sur des positions perdantes',
    rule14Explanation: 'Ajouter à une position perdante est l\'une des erreurs les plus courantes et coûteuses. Si le trade est contre vous, acceptez la perte selon votre plan.',
    rule15Title: 'Laisser courir les gains',
    rule15Explanation: 'Beaucoup de traders coupent les gains prématurément et laissent courir les pertes. Utilisez des trailing stops pour protéger les gains pendant que le prix évolue en votre faveur.',
    
