    // Dow Theory - FRENCH
    dowTheoryTitle: 'Théorie de Dow',
    dowTheoryIntro: 'La Théorie de Dow est le fondement de l\'analyse technique moderne, développée par Charles Dow à la fin du 19ème siècle. Elle établit les principes fondamentaux pour comprendre les mouvements du marché.',
    
    dowPrinciple1Title: '1. Le marché anticipe tout',
    dowPrinciple1Desc: 'Les prix du marché reflètent toutes les informations disponibles : fondamentales, politiques, psychologiques et les anticipations. Tout facteur pouvant affecter l\'offre et la demande est déjà intégré dans le prix.',
    
    dowPrinciple2Title: '2. Le marché a trois tendances',
    dowPrinciple2Desc: 'Tendance Primaire : Mouvement principal du marché durant de 1 à plusieurs années. Tendance Secondaire : Corrections contre la tendance primaire, durant des semaines ou des mois. Tendance Mineure : Fluctuations de court terme durant des jours ou des semaines.',
    
    dowPrinciple3Title: '3. Les tendances principales ont trois phases',
    dowPrinciple3Desc: 'Phase d\'Accumulation : Les investisseurs informés achètent quand le sentiment est négatif. Phase de Participation Publique : Le grand public reconnaît la tendance et participe. Phase de Distribution : Les investisseurs informés vendent quand l\'optimisme est à son maximum.',
    
    dowPrinciple4Title: '4. Les indices doivent se confirmer mutuellement',
    dowPrinciple4Desc: 'Pour qu\'un signal de tendance soit valide, les différents indices du marché doivent se déplacer dans la même direction. Une divergence entre indices suggère que la tendance peut être faible ou fausse.',
    
    dowPrinciple5Title: '5. Le volume doit confirmer la tendance',
    dowPrinciple5Desc: 'Le volume doit augmenter dans la direction de la tendance principale. Dans une tendance haussière, le volume augmente lors des hausses et diminue lors des corrections. L\'inverse se produit dans les tendances baissières.',
    
    dowPrinciple6Title: '6. Une tendance persiste jusqu\'à ce que des signaux clairs indiquent son renversement',
    dowPrinciple6Desc: 'Une tendance reste en vigueur jusqu\'à ce qu\'il y ait une preuve définitive qu\'elle a changé. Les fluctuations mineures ne suffisent pas pour indiquer un changement de tendance. Des modèles de renversement clairs sont nécessaires.',
    
    dowApplicationTitle: 'Application Pratique',
    dowApplicationDesc: 'Pour appliquer la Théorie de Dow : 1) Identifiez la tendance primaire en observant les hauts et les bas. 2) Attendez la confirmation du volume. 3) Cherchez des signaux de renversement uniquement en présence de modèles clairs. 4) Tradez dans la direction de la tendance principale. 5) Utilisez les corrections secondaires comme points d\'entrée.',
    
    dowLimitationsTitle: 'Limitations',
    dowLimitationsDesc: 'La Théorie de Dow ne prédit pas la durée ni l\'ampleur des tendances. Les signaux peuvent arriver tard, après que le mouvement ait déjà commencé. Pas adaptée au trading de très court terme. Fonctionne mieux dans les marchés liquides et de grande capitalisation.',
    
