    tradingPsychologyTitle: 'Psychologie du Trading',
    tradingPsychologyIntro: 'La psychologie est le facteur le plus déterminant entre les traders qui réussissent et ceux qui échouent.',
    cognitiveBiasesTitle: 'Biais Cognitifs',
