    rule1Title: 'Иметь полный торговый план перед торговлей',
    rule1Explanation: 'Торговый план должен включать: анализ рынка, точки входа и выхода, управление рисками и критерии оценки результатов. Без плана вы играете в азартные игры, а не торгуете.',
    rule2Title: 'Никогда не рискуйте более 1-2% капитала в одной сделке',
    rule2Explanation: 'Это правило защищает вас от катастрофических потерь. При капитале в $10,000 ваш максимальный убыток за сделку должен быть $100-200. Это позволит вам пережить серию убытков.',
    rule3Title: 'Следовать торговому плану без исключений',
    rule3Explanation: 'Эмоции - худший враг трейдера. Страх и жадность заставят вас принимать иррациональные решения. Хорошо продуманный план исключает эмоции из уравнения.',
    rule4Title: 'Ждать подтверждения перед входом',
    rule4Explanation: 'Не предвосхищайте движение. Дождитесь, пока цена подтвердит ваш анализ. Преждевременный вход может привести к ненужному стоп лоссу.',
    rule5Title: 'Определить стоп лосс и тейк профит ДО входа',
    rule5Explanation: 'Знание точно где выходить до входа позволяет рассчитать риск/прибыль и принимать объективные решения. Никогда не двигайте стоп лосс вниз.',
    rule6Title: 'Не торговать в эмоциональном состоянии',
    rule6Explanation: 'Если вы расстроены из-за убытка, взволнованы или эйфоричны после прибыли, ваше суждение нарушено. Сделайте перерыв и вернитесь, когда успокоитесь.',
    rule7Title: 'Всегда используйте стоп лосс',
    rule7Explanation: 'Рынок может двигаться против вас сильнее, чем вы думаете. Стоп лосс - ваша страховка от катастрофы. Без него одна сделка может уничтожить ваш счет.',
    rule8Title: 'Анализировать множество таймфреймов',
    rule8Explanation: 'Перед входом проверьте тренд на старших таймфреймах. Вход на 15-минутном графике должен совпадать с трендом на 4-часовом и дневном.',
    rule9Title: 'Торговать только деньгами, которые можете позволить себе потерять',
    rule9Explanation: 'Торговля деньгами на аренду или чрезвычайными фондами подвергнет вас экстремальному эмоциональному давлению. Трейдинг требует рискового капитала, а не жизненно важных средств.',
    rule10Title: 'Вести торговый дневник',
    rule10Explanation: 'Записывайте каждую сделку: вход, выход, причину, эмоцию, результат. Анализируйте паттерны в ваших ошибках и успехах. Улучшение приходит от анализа, а не от большего количества сделок.',
    rule11Title: 'Рынок всегда прав',
    rule11Explanation: 'Не спорьте с рынком. Если ваш анализ оказался неверным, примите убыток и учитесь. Эго дорого обходится в трейдинге.',
    rule12Title: 'Используйте плечо с крайней осторожностью',
    rule12Explanation: 'Плечо усиливает как прибыль, так и убытки. Новичкам не следует использовать более 2-3x. Профессионалы редко используют более 10x.',
    rule13Title: 'Тренд - ваш друг',
    rule13Explanation: 'Торгуйте в направлении основного тренда. Контртрендовая торговля только для очень опытных трейдеров. Легче зарабатывать деньги, следуя за импульсом.',
    rule14Title: 'Никогда не усредняйтесь по убыточным позициям',
    rule14Explanation: 'Добавление к убыточной позиции - одна из самых распространенных и дорогостоящих ошибок. Если сделка идет против вас, примите убыток согласно вашему плану.',
    rule15Title: 'Позволяйте прибыли расти',
    rule15Explanation: 'Многие трейдеры преждевременно фиксируют прибыль и позволяют убыткам расти. Используйте трейлинг стопы для защиты прибыли, пока цена движется в вашу пользу.',
