    // Dow Theory - RUSSIAN
    dowTheoryTitle: 'Теория Доу',
    dowTheoryIntro: 'Теория Доу является основой современного технического анализа, разработанная Чарльзом Доу в конце 19 века. Она устанавливает фундаментальные принципы для понимания движений рынка.',
    
    dowPrinciple1Title: '1. Рынок учитывает всё',
    dowPrinciple1Desc: 'Рыночные цены отражают всю доступную информацию: фундаментальную, политическую, психологическую и ожидания. Любой фактор, который может повлиять на спрос и предложение, уже включен в цену.',
    
    dowPrinciple2Title: '2. У рынка есть три тренда',
    dowPrinciple2Desc: 'Первичный тренд: Основное движение рынка длительностью от 1 до нескольких лет. Вторичный тренд: Коррекции против первичного тренда, длятся недели или месяцы. Малый тренд: Краткосрочные колебания длительностью дни или недели.',
    
    dowPrinciple3Title: '3. Основные тренды имеют три фазы',
    dowPrinciple3Desc: 'Фаза накопления: Информированные инвесторы покупают, когда настроение негативное. Фаза публичного участия: Широкая общественность признает тренд и участвует. Фаза распределения: Информированные инвесторы продают, когда оптимизм на максимуме.',
    
    dowPrinciple4Title: '4. Индексы должны подтверждать друг друга',
    dowPrinciple4Desc: 'Чтобы сигнал тренда был действительным, различные рыночные индексы должны двигаться в одном направлении. Расхождение между индексами предполагает, что тренд может быть слабым или ложным.',
    
    dowPrinciple5Title: '5. Объем должен подтверждать тренд',
    dowPrinciple5Desc: 'Объем должен увеличиваться в направлении основного тренда. В восходящем тренде объем увеличивается на ралли и уменьшается на коррекциях. Противоположное происходит в нисходящих трендах.',
    
    dowPrinciple6Title: '6. Тренд сохраняется до тех пор, пока четкие сигналы не укажут на его разворот',
    dowPrinciple6Desc: 'Тренд остается в силе до тех пор, пока не будет окончательного доказательства его изменения. Незначительных колебаний недостаточно для указания на изменение тренда. Требуются четкие модели разворота.',
    
    dowApplicationTitle: 'Практическое применение',
    dowApplicationDesc: 'Для применения Теории Доу: 1) Определите первичный тренд, наблюдая максимумы и минимумы. 2) Дождитесь подтверждения объемом. 3) Ищите сигналы разворота только при наличии четких паттернов. 4) Торгуйте в направлении основного тренда. 5) Используйте вторичные коррекции как точки входа.',
    
    dowLimitationsTitle: 'Ограничения',
    dowLimitationsDesc: 'Теория Доу не предсказывает продолжительность или величину трендов. Сигналы могут приходить с опозданием, после того как движение уже началось. Не подходит для очень краткосрочной торговли. Лучше всего работает на ликвидных рынках с большой капитализацией.',
    
