    rule1Title: '交易前制定完整的交易计划',
    rule1Explanation: '交易计划应包括：市场分析、进出场点、风险管理和绩效评估标准。没有计划就是在赌博，而不是交易。',
    rule2Title: '单笔交易风险永远不要超过资金的1-2%',
    rule2Explanation: '这条规则保护你免受灾难性损失。如果你有$10,000，每笔交易的最大损失应该是$100-200。这让你能够承受连续亏损。',
    rule3Title: '无例外地遵守交易计划',
    rule3Explanation: '情绪是交易者最大的敌人。恐惧和贪婪会让你做出非理性决定。精心设计的计划能消除情绪因素。',
    rule4Title: '等待确认信号再入场',
    rule4Explanation: '不要预测走势。等待价格确认你的分析。过早入场可能导致不必要的止损。',
    rule5Title: '在入场前就设定止损和止盈',
    rule5Explanation: '入场前就知道准确的出场点，让你能计算风险/回报比并做出客观决策。永远不要向下移动止损。',
    rule6Title: '情绪化时不要交易',
    rule6Explanation: '如果你因亏损而沮丧、焦虑，或因盈利而兴奋，你的判断力会受损。休息一下，冷静后再回来。',
    rule7Title: '始终使用止损',
    rule7Explanation: '市场可能比你想象的更不利于你。止损是你抵御灾难的保险。没有它，一笔交易就能摧毁你的账户。',
    rule8Title: '分析多个时间周期',
    rule8Explanation: '入场前检查更高时间周期的趋势。15分钟图的入场应该与4小时图和日线图的趋势一致。',
    rule9Title: '只用你能承受损失的钱交易',
    rule9Explanation: '用房租钱或应急资金交易会让你承受极大的情绪压力。交易需要风险资本，而不是生活必需资金。',
    rule10Title: '记录交易日志',
    rule10Explanation: '记录每笔交易：入场、出场、原因、情绪、结果。分析你的错误和成功模式。改进来自分析，而不是更多交易。',
    rule11Title: '市场永远是对的',
    rule11Explanation: '不要与市场争论。如果你的分析错了，接受损失并学习。自负在交易中代价高昂。',
    rule12Title: '极其谨慎地使用杠杆',
    rule12Explanation: '杠杆放大盈利也放大亏损。新手不应使用超过2-3倍。专业人士很少使用超过10倍。',
    rule13Title: '趋势是你的朋友',
    rule13Explanation: '顺着主要趋势交易。逆趋势交易只适合非常有经验的交易者。顺势而为更容易赚钱。',
    rule14Title: '永远不要加仓亏损头寸',
    rule14Explanation: '加仓亏损头寸是最常见和代价最高的错误之一。如果交易不利，按计划接受损失。',
    rule15Title: '让利润奔跑',
