    // Dow Theory - CHINESE
    dowTheoryTitle: '道氏理论',
    dowTheoryIntro: '道氏理论是现代技术分析的基础，由查尔斯·道在19世纪末开发。它确立了理解市场运动的基本原则。',
    
    dowPrinciple1Title: '1. 市场消化一切',
    dowPrinciple1Desc: '市场价格反映所有可用信息：基本面、政治、心理和预期。任何可能影响供需的因素都已纳入价格。',
    
    dowPrinciple2Title: '2. 市场有三种趋势',
    dowPrinciple2Desc: '主要趋势：持续1年至数年的主要市场运动。次要趋势：对主要趋势的修正，持续数周或数月。小趋势：持续数天或数周的短期波动。',
    
    dowPrinciple3Title: '3. 主要趋势有三个阶段',
    dowPrinciple3Desc: '积累阶段：知情投资者在情绪消极时买入。公众参与阶段：普通大众认识到趋势并参与。派发阶段：知情投资者在乐观情绪达到顶峰时卖出。',
    
    dowPrinciple4Title: '4. 指数必须相互确认',
    dowPrinciple4Desc: '要使趋势信号有效，不同的市场指数必须朝同一方向移动。指数之间的背离表明趋势可能较弱或虚假。',
    
    dowPrinciple5Title: '5. 成交量必须确认趋势',
    dowPrinciple5Desc: '成交量应在主要趋势方向上增加。在上升趋势中，成交量在上涨时增加，在回调时减少。在下降趋势中情况相反。',
    
    dowPrinciple6Title: '6. 趋势持续直到明确信号表明其反转',
    dowPrinciple6Desc: '趋势保持有效，直到有明确证据表明它已改变。小波动不足以表明趋势变化。需要明确的反转模式。',
    
    dowApplicationTitle: '实际应用',
