    rule4Explanation: '動きを予測しないでください。価格があなたの分析を確認するのを待ちましょう。早すぎるエントリーは不必要なストップロスにつながる可能性があります。',
    rule5Title: 'エントリー前にストップロスとテイクプロフィットを設定',
    rule5Explanation: 'エントリー前に正確な出口を知ることで、リスク/リワード比を計算し、客観的な決定を下すことができます。ストップロスを下に動かさないでください。',
    rule6Title: '感情的なときは取引しない',
    rule6Explanation: '損失で落ち込んでいたり、不安だったり、利益で興奮していたりすると、判断力が損なわれます。休憩を取り、冷静になってから戻りましょう。',
    rule7Title: '常にストップロスを使用',
    rule7Explanation: '市場はあなたが想像する以上に不利に動く可能性があります。ストップロスは災害に対する保険です。それなしでは、1回の取引でアカウントを破壊する可能性があります。',
    rule8Title: '複数のタイムフレームを分析',
    rule8Explanation: 'エントリー前に、より高いタイムフレームのトレンドを確認してください。15分チャートでのエントリーは、4時間足と日足のトレンドと一致するべきです。',
    rule9Title: '失っても構わないお金でのみ取引',
    rule9Explanation: '家賃や緊急資金で取引すると、極度の感情的プレッシャーにさらされます。取引にはリスク資本が必要であり、生活必需資金ではありません。',
    rule10Title: '取引日誌をつける',
