    ivInterpretationDesc_sf001: 'IV（インプライド・ボラティリティ）は、資産の将来のボラティリティに対する市場の期待を反映します。IVが高い（赤）場合は、不確実性が高くprimaが高額であることを示します。IVが低い（青）場合は、市場が落ち着いており、オプションが安価であることを示唆します。skew（歪度）は、ITM/ATM/OTMストライク間の差異を示します。',
