    // Trading Rules (15 rules) - AR
    rule1Title: 'وضع خطة تداول كاملة قبل التداول',
    rule1Explanation: 'يجب أن تتضمن خطة التداول: تحليل السوق، نقاط الدخول والخروج، إدارة المخاطر، ومعايير تقييم الأداء. بدون خطة، أنت تقامر وليس تتداول.',
    rule2Title: 'لا تخاطر أبدًا بأكثر من 1-2٪ من رأس المال في صفقة واحدة',
    rule2Explanation: 'هذه القاعدة تحميك من الخسائر الكارثية. إذا كان لديك $10,000، يجب أن تكون الخسارة القصوى لكل صفقة $100-200. هذا يسمح لك بالنجاة من سلسلة خسائر.',
    rule3Title: 'اتبع خطة التداول بدون استثناءات',
    rule3Explanation: 'العواطف هي أسوأ عدو للمتداول. الخوف والجشع سيجعلانك تتخذ قرارات غير عقلانية. الخطة المصممة جيدًا تزيل العاطفة من المعادلة.',
    rule4Title: 'انتظر التأكيد قبل الدخول',
    rule4Explanation: 'لا تتوقع الحركة. انتظر حتى يؤكد السعر تحليلك. الدخول المبكر قد يؤدي إلى وقف خسارة غير ضروري.',
    rule5Title: 'حدد وقف الخسارة وجني الأرباح قبل الدخول',
    rule5Explanation: 'معرفة مكان الخروج بالضبط قبل الدخول يسمح لك بحساب نسبة المخاطرة/المكافأة واتخاذ قرارات موضوعية. لا تحرك وقف الخسارة للأسفل أبدًا.',
    rule6Title: 'لا تتداول عندما تكون عاطفيًا',
    rule6Explanation: 'إذا كنت محبطًا من خسارة، قلقًا، أو متحمسًا بعد ربح، فإن حكمك معطوب. خذ استراحة وعد عندما تكون هادئًا.',
    rule7Title: 'استخدم دائمًا وقف الخسارة',
    rule7Explanation: 'قد يتحرك السوق ضدك أكثر مما تتخيل. وقف الخسارة هو تأمينك ضد الكارثة. بدونه، يمكن لصفقة واحدة أن تدمر حسابك.',
    rule8Title: 'حلل أطرًا زمنية متعددة',
    rule8Explanation: 'قبل الدخول، تحقق من الاتجاه في الأطر الزمنية الأعلى. يجب أن يتماشى الدخول في الرسم البياني 15 دقيقة مع اتجاه 4 ساعات واليومي.',
    rule9Title: 'تداول فقط بالمال الذي يمكنك تحمل خسارته',
    rule9Explanation: 'التداول بأموال الإيجار أو صناديق الطوارئ سيعرضك لضغط عاطفي شديد. يتطلب التداول رأس مال مخاطر، وليس أموالًا أساسية.',
    rule10Title: 'احتفظ بمذكرات التداول',
    rule10Explanation: 'سجل كل صفقة: الدخول، الخروج، السبب، العاطفة، النتيجة. حلل الأنماط في أخطائك ونجاحاتك. التحسين يأتي من التحليل، وليس من المزيد من الصفقات.',
    rule11Title: 'السوق دائمًا على حق',
    rule11Explanation: 'لا تجادل مع السوق. إذا فشل تحليلك، اقبل الخسارة وتعلم. الأنا مكلفة في التداول.',
    rule12Title: 'استخدم الرافعة المالية بحذر شديد',
    rule12Explanation: 'الرافعة المالية تضخم الأرباح والخسائر. يجب على المبتدئين عدم استخدام أكثر من 2-3x. نادرًا ما يستخدم المحترفون أكثر من 10x.',
    rule13Title: 'الاتجاه صديقك',
    rule13Explanation: 'تداول في اتجاه الاتجاه الرئيسي. التداول العكسي مخصص فقط للمتداولين ذوي الخبرة الكبيرة. من الأسهل كسب المال باتباع الزخم.',
    rule14Title: 'لا تضف أبدًا إلى مراكز خاسرة',
    rule14Explanation: 'الإضافة إلى مركز خاسر هي واحدة من أكثر الأخطاء شيوعًا وتكلفة. إذا كانت الصفقة ضدك، اقبل الخسارة وفقًا لخطتك.',
    rule15Title: 'اترك الأرباح تجري',
    rule15Explanation: 'كثير من المتداولين يقطعون الأرباح مبكرًا ويتركون الخسائر تجري. استخدم وقف الخسارة المتحرك لحماية الأرباح بينما يتحرك السعر لصالحك.',
    
