    // Dow Theory - ARABIC
    dowTheoryTitle: 'نظرية داو',
    dowTheoryIntro: 'نظرية داو هي أساس التحليل الفني الحديث، طورها تشارلز داو في أواخر القرن التاسع عشر. تضع المبادئ الأساسية لفهم حركات السوق.',
    
    dowPrinciple1Title: '1. السوق يخصم كل شيء',
    dowPrinciple1Desc: 'أسعار السوق تعكس جميع المعلومات المتاحة: أساسية، سياسية، نفسية وتوقعات. أي عامل يمكن أن يؤثر على العرض والطلب مدمج بالفعل في السعر.',
    
    dowPrinciple2Title: '2. السوق لديه ثلاثة اتجاهات',
    dowPrinciple2Desc: 'الاتجاه الأساسي: الحركة الرئيسية للسوق التي تستمر من سنة إلى عدة سنوات. الاتجاه الثانوي: التصحيحات ضد الاتجاه الأساسي، تستمر أسابيع أو أشهر. الاتجاه الثانوي: التقلبات قصيرة الأجل التي تستمر أيام أو أسابيع.',
    
    dowPrinciple3Title: '3. الاتجاهات الرئيسية لها ثلاث مراحل',
    dowPrinciple3Desc: 'مرحلة التراكم: المستثمرون المطلعون يشترون عندما تكون المعنويات سلبية. مرحلة المشاركة العامة: الجمهور العام يتعرف على الاتجاه ويشارك. مرحلة التوزيع: المستثمرون المطلعون يبيعون عندما يكون التفاؤل في ذروته.',
    
    dowPrinciple4Title: '4. يجب أن تؤكد المؤشرات بعضها البعض',
    dowPrinciple4Desc: 'لكي تكون إشارة الاتجاه صالحة، يجب أن تتحرك مؤشرات السوق المختلفة في نفس الاتجاه. الاختلاف بين المؤشرات يشير إلى أن الاتجاه قد يكون ضعيفًا أو زائفًا.',
    
    dowPrinciple5Title: '5. يجب أن يؤكد الحجم الاتجاه',
    dowPrinciple5Desc: 'يجب أن يزداد الحجم في اتجاه الاتجاه الرئيسي. في الاتجاه الصاعد، يزداد الحجم في الارتفاعات وينخفض في التصحيحات. يحدث العكس في الاتجاهات الهابطة.',
    
    dowPrinciple6Title: '6. يستمر الاتجاه حتى تشير إشارات واضحة إلى انعكاسه',
    dowPrinciple6Desc: 'يظل الاتجاه ساريًا حتى يكون هناك دليل قاطع على أنه قد تغير. التقلبات الطفيفة ليست كافية للإشارة إلى تغيير الاتجاه. مطلوب أنماط انعكاس واضحة.',
    
    dowApplicationTitle: 'التطبيق العملي',
    dowApplicationDesc: 'لتطبيق نظرية داو: 1) حدد الاتجاه الأساسي من خلال مراقبة القمم والقيعان. 2) انتظر تأكيد الحجم. 3) ابحث عن إشارات الانعكاس فقط عندما تكون هناك أنماط واضحة. 4) تداول في اتجاه الاتجاه الرئيسي. 5) استخدم التصحيحات الثانوية كنقاط دخول.',
    
    dowLimitationsTitle: 'القيود',
    dowLimitationsDesc: 'نظرية داو لا تتنبأ بمدة أو حجم الاتجاهات. قد تصل الإشارات متأخرة، بعد أن تكون الحركة قد بدأت بالفعل. غير مناسبة للتداول قصير الأجل للغاية. تعمل بشكل أفضل في الأسواق السائلة ذات القيمة السوقية الكبيرة.',
    
