export const languages = [
  { code: 'es', name: 'Español', flag: '🇪🇸' },
  { code: 'en', name: 'English', flag: '🇬🇧' },
  { code: 'de', name: 'Deutsch', flag: '🇩🇪' },
  { code: 'fr', name: 'Français', flag: '🇫🇷' },
  { code: 'ru', name: 'Русский', flag: '🇷🇺' },
  { code: 'zh', name: '中文', flag: '🇨🇳' },
  { code: 'ja', name: '日本語', flag: '🇯🇵' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦' },
];

export const useI18nStore = create(
  persist(
    (set, get) => ({
      locale: 'es',
      autoDetected: false, // tracks if we already attempted browser-language detection
      
      setLocale: (locale) => {
        set({ locale });
        // Set RTL for Arabic
        if (locale === 'ar') {
          document.documentElement.dir = 'rtl';
          document.documentElement.lang = 'ar';
        } else {
          document.documentElement.dir = 'ltr';
          document.documentElement.lang = locale;
        }
      },
      
      detectBrowserLanguage: () => {
        if (get().autoDetected) return null; // only run once per device
        if (typeof navigator === 'undefined') return null;
        const supported = ['es','en','de','fr','ru','zh','ja','ar'];
        const raw = (navigator.language || navigator.userLanguage || 'es').toLowerCase();
        const primary = raw.split('-')[0]; // 'en-US' -> 'en'
        // Map common variants
        const mapped = primary === 'iw' ? 'ar' : primary; // legacy hebrew code
        const target = supported.includes(mapped) ? mapped : null;
        // Mark as detected regardless so we don't ask again
        set({ autoDetected: true });
        if (target && target !== get().locale) {
          // Apply via setLocale to also handle dir/lang
          get().setLocale(target);
          return target;
        }
        return null;
      },
      
      t: (key, vars) => {
        const locale = get().locale;
        let str = translations[locale]?.[key] || translations.es[key] || key;
        // Lightweight {var} interpolation for runtime values
        if (vars && typeof str === 'string' && str.includes('{')) {
          str = str.replace(/\{(\w+)\}/g, (_, k) => (
            vars[k] !== undefined ? String(vars[k]) : `{${k}}`
          ));
        }
        return str;
      }
    }),
    {
      name: 'trading-i18n-storage',
      onRehydrateStorage: () => (state) => {
        // Apply dir/lang on initial hydration so RTL works on first load
        if (state?.locale && typeof document !== 'undefined') {
          const loc = state.locale;
          document.documentElement.dir = loc === 'ar' ? 'rtl' : 'ltr';
          document.documentElement.lang = loc;
        }
      },
    }
  )
);

export const useTranslation = () => {
  const { locale, setLocale, t, detectBrowserLanguage } = useI18nStore();
  return { locale, setLocale, t, detectBrowserLanguage };
};
